function updateSiteFreshness() {
    const el = document.getElementById('site-freshness');
    if (!el) return;

    fetch('stats.json', { cache: 'no-store' })
      .then(response => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return response.json();
      })
      .then(data => {
        if (!data.last_update) {
          el.textContent = 'Unavailable';
          el.style.color = '#8b949e';
          el.title = 'No update timestamp available';
          return;
        }
        const lastUpdate = new Date(data.last_update.replace(' UTC', 'Z').replace(' ', 'T'));
        if (isNaN(lastUpdate)) {
          el.textContent = 'Unavailable';
          el.style.color = '#8b949e';
          el.title = 'Invalid timestamp';
          return;
        }
        const now = new Date();
        const diffMs = now - lastUpdate;
        const diffHours = diffMs / (1000 * 60 * 60);
        const diffDays = Math.floor(diffMs / (24 * 60 * 60 * 1000));

        if (diffHours < 2) {
          el.textContent = 'Current';
          el.style.color = '#79c0ff';
          el.title = 'Updated within the last 2 hours';
        } else if (diffHours < 24) {
          el.textContent = 'Stale';
          el.style.color = '#ff5f57';
          el.title = `Updated about ${Math.floor(diffHours)} hours ago`;
        } else {
          el.textContent = 'Needs update';
          el.style.color = '#d29922';
          el.title = `Last updated ${diffDays} day${diffDays !== 1 ? 's' : ''} ago`;
        }
      })
      .catch(error => {
        console.error('Failed to check site freshness:', error);
        el.textContent = 'Unavailable';
        el.style.color = '#8b949e';
        el.title = 'Could not load site data';
      });
  }
```

